with flattened as (select id, service, host, level, latency_ms, status_code, key, attr_value from app_logs lateral view explode(context) t as key, attr_value), with_windows as (select id, service, host, level, latency_ms, status_code, key, attr_value, cume_dist() over (partition by service order by status_code desc) status_code_cume_dist, min(latency_ms) over (partition by level) level_min_latency_ms from flattened), with_windows_app_logs as (select *, rank() over (partition by host, level order by level_min_latency_ms desc) level_min_latency_ms_rank, row_number() over (partition by key, service order by status_code_cume_dist desc, id, key) event_seq from with_windows where service in ('billing', 'checkout')), with_windows_app_logs_2 as (select *, count(latency_ms) over w_part running_count_latency_ms, sum(latency_ms) over w_part running_sum_latency_ms, avg(latency_ms) over w_part running_avg_latency_ms, max(latency_ms) over w_part running_max_latency_ms, round(level_min_latency_ms_rank / sum(level_min_latency_ms_rank) over (partition by service), 4) level_min_latency_ms_rank_share from with_windows_app_logs window w_part as (partition by level order by event_seq, id, key rows between unbounded preceding and current row)), metrics as (select id, service, latency_ms, key, attr_value, status_code_cume_dist, level_min_latency_ms_rank, running_count_latency_ms, running_max_latency_ms, avg(status_code_cume_dist) over w_part status_code_cume_dist_avg_2_prior, avg(status_code_cume_dist) over w_recent status_code_cume_dist_avg_3_prior, avg(running_sum_latency_ms) over (order by running_avg_latency_ms, id, key rows between 3 preceding and current row) running_sum_latency_ms_avg_3 from with_windows_app_logs_2 window w_part as (partition by service order by level_min_latency_ms_rank_share, id, key rows between 2 preceding and 1 preceding), w_recent as (partition by host, key order by running_sum_latency_ms, id, key rows between 3 preceding and 1 preceding)), ranked as (select * from (select *, row_number() over (partition by key, service order by status_code_cume_dist_avg_2_prior desc nulls last, id, key) as rn from metrics) ranked where rn = 1), cleaned as (select *, floor(running_count_latency_ms) running_count_latency_ms_whole, concat(service, '/', key) service_key, coalesce(key, 'UNKNOWN') key_filled from ranked where key is not distinct from 'version') select id, service, key, attr_value, running_count_latency_ms, running_max_latency_ms, status_code_cume_dist_avg_2_prior, status_code_cume_dist_avg_3_prior, running_sum_latency_ms_avg_3 from cleaned;
